import{STRATEGIES,strategyOn,propertyOn,guaranteeReady}from'./scenario.js';
import{riskAnalysis}from'./risk.js';
export function renderStrategies(state,u){const{header,button,icon,esc,euro,notice}=u;return header('Choose what belongs in the scenario.','Switch a property or strategy off to exclude its money, tax effects and risk exposure. Stored inputs are preserved.',button('View risk & decisions '+icon('arrow'),'show-risk','primary'))+notice('These switches change the hypothetical scenario. They do not cancel a mortgage, insurance contract or pension payment. Tax class and statutory insurance remain legal inputs; they are not optional deductions.')+`<div class="section-head"><h2>Properties</h2><span class="tag">${state.properties.filter(propertyOn).length} of ${state.properties.length} enabled</span></div><div class="switch-list">${state.properties.map(p=>`<div class="switch-card ${propertyOn(p)?'':'is-disabled'}"><div><h3>${esc(p.name)}</h3><p>${euro(p.purchasePrice)} purchase · stored monthly rent ${euro(p.rent+p.parking)}${p.rentIncludesParking?' including parking':''}</p><small>${propertyOn(p)?'Included in tax, cash flow, debt, risk and ChatGPT report.':'Excluded everywhere except this saved profile and historical observations.'}</small></div><div class="actions">${button('Edit inputs','open-property','small',`data-id="${esc(p.id)}"`)}${button(propertyOn(p)?'Enabled':'Disabled','toggle-property',`switch-btn ${propertyOn(p)?'is-on':''}`,`data-id="${esc(p.id)}" aria-pressed="${propertyOn(p)}" aria-label="${propertyOn(p)?'Disable':'Enable'} ${esc(p.name)}"`)}</div></div>`).join('')}</div><div class="section-head"><h2>Tax and savings strategies</h2></div><div class="switch-list">${STRATEGIES.map(([key,label,desc])=>{const on=strategyOn(state,key),amount=key==='payrollAllowance'?state.payroll?.annualAllowance||0:state.household[key];return `<div class="switch-card ${on?'':'is-disabled'}"><div><h3>${esc(label)}</h3><p>${desc} · stored ${euro(amount)} / ${['otherDeductions','payrollAllowance'].includes(key)?'year':'month'}</p><small>${on?'Included when applicable.':'Contribution and associated benefit excluded; input retained.'}</small></div><div class="actions">${button('Edit amounts',key==='payrollAllowance'?'show-payroll':'show-tax','small')}${button(on?'Enabled':'Disabled','toggle-strategy',`switch-btn ${on?'is-on':''}`,`data-key="${key}" aria-pressed="${on}" aria-label="${on?'Disable':'Enable'} ${esc(label)}"`)}</div></div>`;}).join('')}</div><div class="section-head"><h2>Future vacancy-rent guarantees</h2></div>${notice('Enter the exact start, expiry, premium and coverage of any planned rent guarantee. No future premium or coverage percentage has been invented. A plan gets stress-protection credit only after all terms are entered and confirmed.')}<div class="switch-list">${state.properties.map(p=>{const g=p.guaranteePlan;return `<div class="switch-card ${propertyOn(p)?'':'is-disabled'}"><div><h3>${esc(p.name)} · planned guarantee</h3><p>${g.startYear}–${g.endYear} · premium ${g.annualPremium==null?'not priced':euro(g.annualPremium)+' / year'} · vacancy cover ${g.coveragePercent==null?'unknown':g.coveragePercent+'%'}</p><small>${!propertyOn(p)?'Property disabled: guarantee excluded.':guaranteeReady(p)?'Confirmed plan included in cash costs and covered-year vacancy stress.':'Unverified plan: no protection credited; an enabled unpriced plan blocks the score.'}</small></div><div class="actions">${button('Enter terms','open-guarantee','small',`data-id="${esc(p.id)}"`)}${button(g.enabled?'Enabled':'Disabled','toggle-guarantee',`switch-btn ${g.enabled?'is-on':''}`,`data-id="${esc(p.id)}" aria-pressed="${g.enabled}" aria-label="${g.enabled?'Disable':'Enable'} guarantee for ${esc(p.name)}"`)}</div></div>`;}).join('')}</div><div class="section-head"><h2>Data confirmation</h2></div><div class="card"><p class="small-text">Starter properties are fictional examples with unconfirmed inputs. Count parking once and choose an explicit rent-growth scenario. Confirm dates, loan terms, owner costs and growth assumptions in each active property’s Purchase & AfA tab.</p></div>`;}
export function renderRisk(state,u){const{header,button,icon,esc,euro,notice,stat,field,check,sectionCard}=u,r=riskAnalysis(state),f=state.risk;const fmt=x=>x==null?'—':euro(x,2);const first=r.rows[0],low=r.essentialMonthlyLow,high=r.essentialMonthlyHigh;return header('Does this scenario leave you enough room?','Cash resilience and purchase comparisons, based only on enabled properties and strategies.',button('Scenario switches','show-scenarios')+button('Prepare ChatGPT analysis '+icon('arrow'),'prepare-ai','primary'))+`<div class="stats">${stat('Resilience score · weakest year',r.score==null?'Not rated':r.score+' / 100',r.score==null?'Active inputs or stress choices need confirmation':`${r.rating} · weakest year ${r.worstYear}`,'chart',r.score!=null&&r.score>=75)}${stat('First-year monthly headroom',fmt(first.freeMonthly),'After entered budget, optional earmarks and consumer debt','wallet')}${stat('Entered emergency cash',fmt(f.liquidCash),f.cashApproximate?'Approximate user input · update as needed':'Bank cash only · no investment-sale assumption','building')}${stat('Reserve coverage · first year',first.reserveMonths==null?'—':first.reserveMonths.toFixed(1)+' months','Cash / modeled obligations · rent not credited to emergency buffer','tax')}</div>${notice('This is a disclosed heuristic score of affordability and resilience, not an AI prediction, lending decision or expected investment return. No score is issued until active inputs and chosen stress parameters are complete. Unknown fees and unconfirmed contract terms remain visible.',r.score==null)}<div class="split"><div class="card"><h2>Your entered household budget</h2><div class="break-row"><span>Warm rent + electricity + internet + insurance + food</span><strong>${euro(f.essentialMonthly??0)} / mo</strong></div><p class="small-text">Enter the total of your verified household expenses in the editable field below.</p><div class="break-row"><span>Other annual costs</span><strong>${fmt(f.otherAnnualLow)}–${fmt(f.otherAnnualHigh)} / year</strong></div><div class="break-row"><span>Essential monthly range</span><strong>${fmt(low)}–${fmt(high)}</strong></div><div class="break-row"><span>Travel + optional learning/driving earmarks</span><strong>${fmt(f.optionalMonthly)} / mo</strong></div><div class="break-row"><span>Consumer-loan payments</span><strong>${fmt(f.consumerMonthly)} / mo through ${esc(f.consumerEnd||'unknown')}</strong></div><p class="small-text">Calculations use the upper annual-expense estimate. Consumer-loan payments stop after the entered final month; the final year is prorated. Pension deposits are taken from enabled strategies, so they are not added to living costs a second time. The first-year budget is a nominal planning scenario, not an inflation forecast.</p></div><div class="card"><h2>${r.score==null?'What is still missing?':'Score components · weakest year'}</h2>${r.score==null?`<ul class="note-list">${r.missing.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>`:r.components.map(c=>`<div class="break-row"><span>${c.label}</span><strong>${c.points.toFixed(1)} / ${c.max}</strong></div><p class="small-text">${esc(c.formula)}</p>`).join('')}<p class="small-text">Score caps: negative base headroom or a combined annual deficit larger than available cash, or an immediate repair hit above that cash, caps at39. Less than three months of reserves, or a fundable negative combined-stress year, caps at59. Bands:75+ stronger resilience,50–74 needs attention, below50 high cash-flow risk. These thresholds are design choices, not regulatory standards.</p></div></div><div class="section-head"><h2>Ten-year risk matrix · ${r.startYear}–${r.endYear}</h2><span class="tag">Amounts in EUR / month unless labeled</span></div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Year</th><th>Property cash needed before tax</th><th>Base headroom</th><th>Rent stress</th><th>Salary stress</th><th>Rate stress¹</th><th>Combined²</th><th>Reserve months</th><th>Rental debt coverage</th><th>Year-end debt</th><th>Score</th></tr></thead><tbody>${r.rows.map(v=>`<tr><td>${v.year}${v.guarantees.length?' <span class="badge">Cover confirmed</span>':''}</td><td>${fmt(v.cashNeededBeforeTax)}</td><td class="${v.freeMonthly<0?'negative':'positive'}">${fmt(v.freeMonthly)}</td><td class="${v.vacancyFree<0?'negative':''}">${fmt(v.vacancyFree)}</td><td class="${v.salaryFree<0?'negative':''}">${fmt(v.salaryFree)}</td><td>${fmt(v.rateFree)}</td><td class="${v.combinedFree<0?'negative':''}">${fmt(v.combinedFree)}</td><td>${v.reserveMonths==null?'—':v.reserveMonths.toFixed(1)}</td><td>${v.coverage==null?'No property debt':v.coverage.toFixed(2)+'×'}</td><td>${euro(v.debt)}</td><td>${v.score==null?'Not rated':v.score}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>¹ Extra-interest sensitivity after fixation, holding principal repayment pace. ² Combined rent + gross-pay + rate shock and the one-off portfolio repair amount, expressed as annualized monthly burden.</span></div></div><p class="small-text">Property cash needed before tax is the enabled portfolio’s funding gap after rental receipts and full cash payments, with no tax relief credited. It excludes household living costs. Each year tests an independent shock in that year. Emergency cash is not increased by hypothetical positive savings; base deficits draw it down. No unemployment benefit, investment sale, house appreciation or future refinancing offer is assumed. Future tax and social parameters remain the documented2026 model.</p><div class="section-head"><h2>What does each enabled purchase add?</h2></div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Remove this property from the enabled scenario</th><th>Its ten-year tax benefit</th><th>Its ten-year cash effect</th><th>Its principal repaid</th><th>Score without it</th></tr></thead><tbody>${r.deltas.map(d=>`<tr><td>${esc(d.name)}</td><td>${fmt(d.taxBenefit)}</td><td class="${d.cashEffect<0?'negative':'positive'}">${fmt(d.cashEffect)}</td><td>${fmt(d.principal)}</td><td>${d.scoreWithout==null?'Inputs incomplete':d.scoreWithout+' / 100'}</td></tr>`).join('')||'<tr><td colspan="5">No property enabled. All property cash flow, debt and tax benefits are excluded.</td></tr>'}</tbody></table></div></div><p class="small-text">These are exact model differences between current enabled inputs and the same scenario with that property removed. Per-property removal effects do not necessarily sum because tax is progressive. Principal is not cash profit; sale price, selling costs and outstanding debt would also matter to a sale outcome.</p><div class="section-head"><h2>Dynamic calculated findings</h2><span class="tag">Rules-based · not AI-generated</span></div><div class="finding-list">${r.recommendations.map(rec=>`<div class="finding ${rec.level}"><span class="badge">${esc(rec.level)}</span><p>${esc(rec.text)}</p></div>`).join('')}</div><form id="risk-form">${sectionCard('Your risk and budget inputs','Exact amounts can be entered here. Blank means unknown, never an invented estimate.',`<div class="form-grid">${field('liquidCash','Liquid emergency bank cash · €',f.liquidCash,'number','Excludes ETFs, P2P, property equity and pension assets.',{nullable:true})}${field('essentialMonthly','Core essential household spending · € / mo',f.essentialMonthly,'number','Includes warm rent; excludes property payments, pension deposits and consumer loan.',{nullable:true})}${field('otherAnnualLow','Other yearly costs · lower €',f.otherAnnualLow,'number','Enter a yearly lower estimate, not a monthly amount.',{nullable:true})}${field('otherAnnualHigh','Other yearly costs · upper €',f.otherAnnualHigh,'number','Upper figure used for cash resilience.',{nullable:true})}${field('optionalMonthly','Travel / optional learning earmarks · € / mo',f.optionalMonthly,'number','Enter 0 to model pausing optional spending.',{nullable:true})}${field('consumerMonthly','Consumer-loan payment · € / mo',f.consumerMonthly,'number','Separate from every property loan.',{nullable:true})}${field('consumerEnd','Consumer-loan final repayment month',f.consumerEnd,'month')}${check('cashApproximate','Emergency cash is approximate',f.cashApproximate)}${check('cashAfterCapital','Cash shown remains after any planned own-capital payments',f.cashAfterCapital)}${field('startYear','First full risk-forecast year',f.startYear,'number','Ten calendar years, e.g.2027–2036.',{min:2026,max:2100,step:1})}</div>`)}${sectionCard('Choose hypothetical stress tests','These are user-chosen what-if parameters, not claims about future outcomes.',`<div class="form-grid">${field('vacancyStressPercent','Annual rent-collection reduction · %',f.vacancyStressPercent,'number','Beyond the base vacancy input; confirmed guarantee may cover part in eligible years.',{nullable:true,max:100})}${field('salaryStressPercent','Gross salary reduction · %',f.salaryStressPercent,'number','Nonzero shocks recalculate tax / statutory insurance; manual insurance overrides are replaced for that hypothetical stress. No benefit income assumed.',{nullable:true,max:100})}${field('repairStress','One-off repair hit · total portfolio €',f.repairStress,'number','Conservative cash hit; no automatic tax refund assumed.',{nullable:true})}${field('rateShockPoints','Interest-rate increase after fixation · percentage points',f.rateShockPoints,'number','Extra interest on the modeled remaining balance.',{nullable:true,max:25})}</div><p class="small-text">Optional preset:20% fewer collected rents,20% less gross salary,€5,000 one-off portfolio repairs and+2 percentage points interest after fixation. It is applied only when you click the button.</p>${button('Use this hypothetical stress preset','stress-preset','small')}`)}<div class="save-bar"><small>All results and recommendations follow enabled items only.</small><button class="btn primary" type="submit">${icon('check')} Save & recalculate risk</button></div></form><div class="card ai-handoff"><h2>Ask ChatGPT about this exact enabled scenario</h2><p class="small-text">As requested, this uses a ChatGPT handoff without an API key. Prepare a fresh report, copy it, then paste it into ChatGPT. The report contains enabled items and their calculations; no disabled properties or disabled contribution amounts are included. Nothing is sent automatically. This app does not claim that its local findings are an AI response.</p><div class="actions">${button('Prepare fresh report','prepare-ai','primary')}${button('Copy prepared report','copy-ai')}${button('Download analysis prompt','download-ai')}<a class="btn" href="https://chatgpt.com/" target="_blank" rel="noreferrer">Open ChatGPT ↗</a></div><textarea id="ai-report" class="handoff-text" readonly rows="8" placeholder="Prepare a report from the currently enabled scenario."></textarea></div><details><summary>Full methodology and calculation limits</summary><p>${esc(r.method)}</p><p>Debt/purchase-cost is a proxy, not a current market loan-to-value ratio. Rental cash debt coverage includes entered reserve/capital payments as cash costs. Incomplete legal/tax basis, reduced-rent rules, guarantee exclusions and unknown costs can change the outcome. Seller guarantees are not treated as an insured asset without confirmed terms.</p></details>`;}
